<script setup>
import { ref, reactive, computed, inject, watch } from 'vue'
import { useAuthStore } from '../../stores/auth'
import { adminDriversApi } from '../../api/drivers.api'
import { branchesApi } from '../../api/branches.api'
import { useServerList } from '../../composables/useServerList'
import { useApiState, useApiMutation } from '../../composables/useApiState'
import { useModalDraft } from '../../composables/useModalDraft'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AdminIcon from '../../components/admin/AdminIcon.vue'
import AdminModal from '../../components/admin/AdminModal.vue'
import DomainFields from '../../components/admin/DomainFields.vue'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
import AdminDriverAssignment from '../../components/orders/AdminDriverAssignment.vue'
import { formatCurrency } from '../../utils/formatters'
import { driverTime, deliveryLabels } from '../../constants/driverDelivery'
const auth = useAuthStore(), { notify, confirmAction } = inject('admin'), list = useServerList(adminDriversApi), branches = useApiState([]), detail = useApiState(), collections = useApiState(), mutation = useApiMutation()
const open = ref(false), detailOpen = ref(false), editing = ref(null), collectionPage = ref(1), selected = ref([]), amount = ref(''), reason = ref(''), assignmentBusy = ref(false)
const form = reactive({ name: '', phone: '', email: '', password: '', branch_uuid: '', enabled: true, available: true })
const fields = computed(() => [
  { key: 'name', label: 'اسم المندوب', required: true, max: 150 },
  { key: 'phone', label: 'رقم الجوال', required: true, help: 'مثال: 0551234567', type: 'tel', max: 16, pattern: '\\+[1-9][0-9]{7,14}' },
  { key: 'email', label: 'البريد الإلكتروني (اختياري)', type: 'email' },
  { key: 'password', label: editing.value?'كلمة مرور جديدة (اختياري)':'كلمة المرور', type: 'password', required: !editing.value, minlength: 12, max: 72, help: '12 حرفًا على الأقل، مع أحرف كبيرة وصغيرة وأرقام.' },
  { key: 'branch_uuid', label: 'الفرع', type: 'select', required: true, options: (branches.data.value || []).map(branch => ({ value: branch.id, label: branch.name })) },
  { key: 'enabled', label: 'تفعيل المندوب لاستقبال الطلبات', type: 'checkbox' },
  { key: 'available', label: 'متاح للطلبات', type: 'checkbox' },
])
const beforeClose = useModalDraft(open, form, mutation.busy)
async function edit(driver) { editing.value = driver; mutation.error.value = null; Object.assign(form, { name: driver?.name || '', phone: driver?.phone || '', email: driver?.email || '', password: '', branch_uuid: driver?.branch?.id || branches.data.value?.[0]?.id || '', enabled: driver?.enabled ?? true, available: driver?.available ?? true }); open.value = true }
function payload(driver, enabled) { return { name: driver.name, phone: driver.phone, email: driver.email, branch_uuid: driver.branch.id, enabled, available: enabled && driver.available } }
async function save() {
  const body = { ...form, email: form.email || null }; if (!body.password) delete body.password
  const result = await mutation.run(() => editing.value ? adminDriversApi.update(editing.value.id, body) : adminDriversApi.create(body))
  if (result.ok) { open.value = false; form.password = ''; notify('تم حفظ المندوب.'); await list.load() }
}
async function toggle(driver) {
  if (!await confirmAction((driver.enabled?'إيقاف':'تفعيل') + ' استقبال الطلبات للمندوب ' + driver.name + '؟')) return
  const result = await mutation.run(() => adminDriversApi.update(driver.id, payload(driver, !driver.enabled)))
  if (result.ok) { notify('تم تحديث حالة المندوب.'); await list.load() }
}
async function loadCollections() { return collections.run(signal => adminDriversApi.collections(detail.data.value.id, { page: collectionPage.value, per_page: 20 }, signal)) }
async function show(driver) {
  selected.value = []; amount.value = reason.value = ''; collectionPage.value = 1; mutation.error.value = null
  const value = await detail.run(signal => adminDriversApi.show(driver.id, signal)); if (!value) return
  detailOpen.value = true; await loadCollections()
}
async function refreshDetail() { const id = detail.data.value?.id; if (id) await detail.run(signal => adminDriversApi.show(id, signal)); await list.load() }
const selectedTotal = computed(() => (collections.data.value?.data || []).filter(item => selected.value.includes(item.id)).reduce((sum,item) => sum + Math.round(Number(item.amount) * 100), 0) / 100)
async function settle() {
  if (!selected.value.length || !await confirmAction('تأكيد استلام العهدة النقدية من المندوب وتسويتها؟')) return
  const result = await mutation.run(() => adminDriversApi.settle(detail.data.value.id, { collection_uuids: selected.value, amount: amount.value, reason: reason.value }))
  if (result.ok) { selected.value = []; amount.value = reason.value = ''; notify('تمت تسوية العهدة النقدية.'); await refreshDetail(); await loadCollections() }
}
const assignmentOrder = computed(() => detail.data.value?.current_order ? { id: detail.data.value.current_order.id, type: 'delivery', branch: detail.data.value.branch, delivery: { status: detail.data.value.current_order.delivery_status, driver: { name: detail.data.value.name } } } : null)
watch(open, value => { if (!value) form.password = '' })
void list.load(); void branches.run(() => branchesApi.publicList())
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>مناديب التوصيل</h1><p class="muted">الفروع والتوفر والطلبات والعهد النقدية</p></div><button v-if="auth.can('drivers.manage')" class="button" :disabled="mutation.busy.value || branches.loading.value" @click="edit(null)">إضافة مندوب</button></AdminPageHeader><section class="panel"><form class="toolbar" @submit.prevent="list.search"><input v-model="list.filters.search" type="search" aria-label="بحث المناديب" placeholder="اسم المندوب أو رقم الجوال" maxlength="150"><button class="button" :disabled="list.state.loading.value">بحث</button><button type="button" class="row-button" :disabled="list.state.loading.value" @click="list.load">تحديث</button></form><ApiFeedback :loading="list.state.loading.value" :error="list.state.error.value || detail.error.value" @retry="list.load"/><div v-if="list.state.data.value" class="table-wrap"><table v-admin-table><thead><tr><th>المندوب</th><th>الفرع</th><th>التوفر</th><th>الطلب الحالي</th><th>تم تسليمها</th><th>عهدة غير مسواة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="driver in list.state.data.value.data" :key="driver.id"><td>{{ driver.name }}<small class="driver-admin-phone"><bdi>{{ driver.phone }}</bdi></small></td><td>{{ driver.branch?.name || 'غير مرتبط بفرع' }}</td><td><span class="badge" :class="driver.enabled && driver.available?'good':'off'">{{ !driver.enabled?'موقوف':driver.available?'متاح':'غير متاح' }}</span></td><td>{{ driver.current_order?'#'+driver.current_order.order_number:'—' }}</td><td>{{ driver.delivered_count }}</td><td>{{ formatCurrency(driver.unsettled_cash || 0) }}</td><td><div class="admin-row-actions"><button class="row-button" :disabled="mutation.busy.value || detail.loading.value" @click="show(driver)">التفاصيل</button><button v-if="auth.can('drivers.manage')" class="row-button" :disabled="mutation.busy.value" @click="edit(driver)">تعديل</button><button v-if="auth.can('drivers.manage') && driver.branch" class="row-button" :class="{danger:driver.enabled}" :disabled="mutation.busy.value" @click="toggle(driver)">{{ driver.enabled?'إيقاف':'تفعيل' }}</button></div></td></tr></tbody></table><p v-if="!list.state.data.value.data.length" class="empty">لا يوجد مناديب مطابقون.</p></div><ApiPagination :meta="list.state.data.value?.meta" :links="list.state.data.value?.links" :busy="list.state.loading.value" @page="list.changePage"/><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></section><AdminModal v-model:open="open" :before-close="beforeClose" :title="editing?'تعديل المندوب':'إضافة مندوب'" :busy="mutation.busy.value" @submit="save"><DomainFields :fields="fields" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value"/><ApiFeedback :error="branches.error.value || mutation.error.value" @retry="branches.run(()=>branchesApi.publicList())"/><div class="form-actions"><button class="button" :disabled="mutation.busy.value || !form.branch_uuid">حفظ المندوب</button></div></AdminModal><AdminModal v-model:open="detailOpen" :title="detail.data.value?.name || 'تفاصيل المندوب'" :busy="mutation.busy.value || assignmentBusy" size="large" @submit="settle"><template v-if="detail.data.value"><div class="driver-detail-overview"><div class="driver-detail-identity"><span class="driver-detail-branch"><AdminIcon name="map-pin"/>{{ detail.data.value.branch?.name || 'غير مرتبط بفرع' }}</span><span class="badge driver-detail-status" :class="detail.data.value.enabled?'good':'off'"><span class="driver-status-dot"/>{{ detail.data.value.enabled?'مفعّل':'موقوف' }}</span></div><dl class="driver-detail-stats"><div class="driver-detail-stat"><span class="driver-stat-icon"><AdminIcon name="truck"/></span><div><dt>الطلبات المسلمة</dt><dd>{{ detail.data.value.delivered_count }}</dd></div></div><div class="driver-detail-stat driver-cash-stat"><span class="driver-stat-icon"><AdminIcon name="wallet"/></span><div><dt>العهدة غير المسواة</dt><dd>{{ formatCurrency(detail.data.value.unsettled_cash || 0) }}</dd></div></div></dl></div><div v-if="detail.data.value.current_order"><p>الطلب الحالي: <RouterLink v-if="auth.can('orders.view')" :to="'/admin/orders/'+detail.data.value.current_order.id" @click="detailOpen=false">#{{ detail.data.value.current_order.order_number }}</RouterLink><span v-else>#{{ detail.data.value.current_order.order_number }}</span> · {{ deliveryLabels[detail.data.value.current_order.delivery_status] }}</p><AdminDriverAssignment :order="assignmentOrder" :reload="refreshDetail" @active="assignmentBusy=$event"/></div><h3 class="driver-detail-section-title"><AdminIcon name="wallet"/>التحصيلات والتسوية</h3><ApiFeedback :loading="collections.loading.value" :error="collections.error.value" @retry="loadCollections"/><div class="driver-collection-list"><label v-for="item in collections.data.value?.data || []" :key="item.id" class="driver-collection-row"><input v-if="auth.can('drivers.settle_cash') && !item.settled_at" v-model="selected" type="checkbox" :value="item.id" :disabled="mutation.busy.value"><span>طلب #{{ item.order.order_number }}<small>{{ driverTime(item.collected_at) }}<span v-if="item.settlement"> · استلمها {{ item.settlement.cashier }}</span></small></span><strong>{{ formatCurrency(item.amount) }}</strong><span class="badge" :class="item.settled_at?'good':'off'">{{ item.settled_at?'مسواة':'غير مسواة' }}</span></label><p v-if="collections.data.value && !collections.data.value.data.length" class="empty">لا توجد مبالغ محصلة.</p></div><ApiPagination :meta="collections.data.value?.meta" :links="collections.data.value?.links" :busy="collections.loading.value || mutation.busy.value" @page="collectionPage=$event;selected=[];loadCollections()"/><div v-if="auth.can('drivers.settle_cash') && selected.length" class="driver-settlement-form"><p>مجموع التحصيلات المختارة: <strong>{{ formatCurrency(selectedTotal) }}</strong></p><label class="field">المبلغ المستلم من المندوب<input v-model="amount" type="number" min="0" step="0.01" required :disabled="mutation.busy.value"></label><label class="field">ملاحظة التسوية<textarea v-model="reason" required minlength="3" maxlength="1000" rows="2" :disabled="mutation.busy.value"/></label><p class="muted">أكد التسوية بعد استلام المبلغ فعليًا. تُسجل باسم حسابك الحالي.</p><button class="button" :disabled="mutation.busy.value">تأكيد استلام العهدة</button></div><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></template></AdminModal></main></template>
<style scoped>.driver-admin-phone{display:block;margin-top:5px;color:var(--muted)}.driver-collection-list{display:grid;gap:10px;margin-block:16px}.driver-collection-row{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:8px;flex-wrap:wrap}.driver-collection-row>span:first-of-type{flex:1;min-width:110px}.driver-collection-row small{display:block;margin-top:5px;color:var(--muted)}.driver-settlement-form{display:grid;gap:14px;margin-top:20px}.driver-settlement-form .field{display:grid;gap:8px}.driver-settlement-form input,.driver-settlement-form textarea{font:inherit;width:100%;min-height:44px;border:1px solid var(--line);border-radius:8px;padding:10px}.driver-collection-row input{width:18px;height:18px}.driver-detail-overview{margin-bottom:24px}.driver-detail-identity{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;padding-bottom:18px}.driver-detail-branch{display:inline-flex;align-items:center;gap:8px;font-size:14px;font-weight:700;color:var(--burgundy)}.driver-detail-branch .icon{width:19px;height:19px;flex-shrink:0}.driver-detail-status{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:20px}.driver-status-dot{width:6px;height:6px;border-radius:50%;background:currentColor}.driver-detail-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:0}.driver-detail-stat{display:flex;align-items:center;gap:12px;padding:18px;background:var(--cream);border:1px solid var(--line);border-radius:10px;min-width:0}.driver-detail-stat>div{min-width:0}.driver-stat-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:10px;background:#efe4e5;color:var(--burgundy);flex-shrink:0}.driver-stat-icon .icon{width:22px;height:22px}.driver-cash-stat .driver-stat-icon{background:#f5ecd9;color:#947039}.driver-detail-stat dt{font-size:12px;color:var(--muted)}.driver-detail-stat dd{margin:4px 0 0;font-size:24px;font-weight:700;line-height:1.4;color:var(--burgundy);overflow-wrap:anywhere}.driver-detail-section-title{display:flex;align-items:center;gap:9px;font-size:15px;padding-top:20px;margin-top:20px;border-top:1px solid var(--line);color:var(--burgundy)}.driver-detail-section-title .icon{width:20px;height:20px}@media(max-width:520px){.driver-detail-stats{grid-template-columns:1fr;gap:10px}.driver-detail-stat{padding:14px}.driver-detail-stat dd{font-size:22px}}</style>
